package main

import (
	"log"
	"net/http"

	"example.com/orders/internal/handlers"
)

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/orders", handlers.ListOrders)
	mux.HandleFunc("/orders/new", handlers.CreateOrder)
	log.Fatal(http.ListenAndServe(":8080", mux))
}

package handlers

import (
	"encoding/json"
	"net/http"

	"example.com/orders/internal/store"
)

func ListOrders(w http.ResponseWriter, r *http.Request) {
	orders := store.AllOrders()
	json.NewEncoder(w).Encode(orders)
}

func CreateOrder(w http.ResponseWriter, r *http.Request) {
	var order store.Order
	if err := json.NewDecoder(r.Body).Decode(&order); err != nil {
		http.Error(w, "invalid order", http.StatusBadRequest)
		return
	}
	store.SaveOrder(order)
	w.WriteHeader(http.StatusCreated)
}

package store

type Order struct {
	ID       int     `json:"id"`
	Customer string  `json:"customer"`
	Total    float64 `json:"total"`
}

var orders []Order

func AllOrders() []Order {
	return orders
}

func SaveOrder(order Order) {
	orders = append(orders, order)
}

package store

import "testing"

func TestSaveOrder(t *testing.T) {
	SaveOrder(Order{ID: 1, Customer: "acme", Total: 12.5})
	if len(AllOrders()) != 1 {
		t.Fatal("order not saved")
	}
}

